import numpy as np
import seaborn as sns

def task_func(P, T):
    if not isinstance(P, np.ndarray) or not isinstance(T, np.ndarray):
        raise TypeError("Expected numpy array inputs.")
    if P.ndim != 2:
        raise ValueError("P must be a 2D numpy matrix/array.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D numpy tensor.")
    if P.shape[1] != T.shape[0]:
        raise ValueError("The number of columns in P must match the first dimension of T.")

    result = np.einsum("ij,jkl->ikl", P, T)
    result_2d = result.reshape(result.shape[0], -1)
    ax = sns.heatmap(result_2d)

    return result, ax
